$file = "X:\code\copilot-worktrees\P09\cirvine-msft-animated-pancake\assets\undo.txt"
$content = Get-Content $file -Raw
$lines = $content -split "`n" | Where-Object { $_ -ne "" }

# Validation results
Write-Host "=== FILE VALIDATION ===" -ForegroundColor Cyan

# Line count
Write-Host "Total lines: $($lines.Count) (Expected: 12)" -ForegroundColor $(if($lines.Count -eq 12) {"Green"} else {"Red"})

# Check each line
Write-Host "`n=== LINE DETAILS ===" -ForegroundColor Cyan
for ($i = 0; $i -lt $lines.Count; $i++) {
    $line = $lines[$i]
    $len = $line.Length
    $lenOk = $len -ge 20 -and $len -le 48

    # Check for trailing space
    $trailingSpace = $line -match '\s$'

    # Check valid characters: A-Z 0-9 space + | / \ _ * . # ( ) : = -
    # Manual check instead of regex
    $validChars = $true
    foreach ($char in $line.ToCharArray()) {
        $code = [byte][char]$char
        if (-not (
            ($code -ge 65 -and $code -le 90) -or  # A-Z
            ($code -ge 48 -and $code -le 57) -or  # 0-9
            $char -eq ' ' -or $char -eq '+' -or $char -eq '|' -or $char -eq '/' -or
            $char -eq '\' -or $char -eq '_' -or $char -eq '*' -or $char -eq '.' -or
            $char -eq '#' -or $char -eq '(' -or $char -eq ')' -or $char -eq ':' -or
            $char -eq '=' -or $char -eq '-'
        )) {
            $validChars = $false
            break
        }
    }

    $color = if ($lenOk -and $validChars -and -not $trailingSpace) {"Green"} else {"Red"}
    Write-Host "Line $($i + 1): [$len chars] `"$line`"" -ForegroundColor $color
    if (-not $lenOk) { Write-Host "  ERROR: Length $len not in range 20-48" -ForegroundColor Red }
    if (-not $validChars) { Write-Host "  ERROR: Invalid characters" -ForegroundColor Red }
    if ($trailingSpace) { Write-Host "  ERROR: Has trailing whitespace" -ForegroundColor Red }
}

# Check for UNDO
$hasUndo = $content -match 'UNDO'
Write-Host "`nContains 'UNDO': $(if($hasUndo) {"Yes"} else {"No"})" -ForegroundColor $(if($hasUndo) {"Green"} else {"Red"})

# Check ending
$endsWithNewline = $content.EndsWith("`n")
$endsWithDoubleNewline = $content.EndsWith("`n`n")
Write-Host "Ends with single newline: $(if($endsWithNewline -and -not $endsWithDoubleNewline) {"Yes"} else {"No"})" -ForegroundColor $(if($endsWithNewline -and -not $endsWithDoubleNewline) {"Green"} else {"Red"})

# ASCII check
$allAscii = $true
foreach ($char in $content.ToCharArray()) {
    if ([byte][char]$char -gt 127) {
        $allAscii = $false
        break
    }
}
Write-Host "ASCII only: $(if($allAscii) {"Yes"} else {"No"})" -ForegroundColor $(if($allAscii) {"Green"} else {"Red"})

# Overall result
$allValid = ($lines.Count -eq 12) -and $hasUndo -and $endsWithNewline -and -not $endsWithDoubleNewline -and $allAscii
for ($i = 0; $i -lt $lines.Count; $i++) {
    $line = $lines[$i]
    $len = $line.Length
    if ($len -lt 20 -or $len -gt 48) { $allValid = $false }
    if ($line -match '\s$') { $allValid = $false }
}

Write-Host "`n=== RESULT ===" -ForegroundColor $(if($allValid) {"Green"} else {"Red"})
Write-Host "$(if($allValid) {'✓ ALL CONSTRAINTS SATISFIED'} else {'✗ VALIDATION FAILED'})"

