31.             $task = [ordered]@{
32.                 id = $nextId
33.                 title = $title.Trim()
34.                 description = if ($options.Contains('description')) { [string]$options['description'] } else { '' }
35.                 status = 'pending'
36.                 createdAt = [DateTimeOffset]::UtcNow.ToString('o')
