51.         }
52.         'list' {
53.             Assert-KnownOptions -Options $options -Allowed @('data-file', 'json')
54.             $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
55.             if ($asJson) {
56.                 Write-TaskForgeOutput -Value $tasks -AsJson $true
57.             }
58.             elseif ($tasks.Count -eq 0) {
59.                 'No tasks.'
60.             }
61.             else {
62.                 $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
63.             }
64.         }
65.         'complete' {
66.             Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json')
67.             $idText = Get-RequiredOption -Options $options -Name 'id'
68.             $id = 0
69.             if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
