118.             $summary = [pscustomobject]@{ removedId = $id }
119.             if ($asJson) {
120.                 Write-TaskForgeOutput -Value $summary -AsJson $true
121.             }
122.             else {
123.                 "Removed task $id."
124.             }
125.         }
