134.                 "Undid $($summary.undone) for task $($summary.taskId)."
135.             }
136.         }
137.         'help' {
138.             Assert-KnownOptions -Options $options -Allowed @()
139.             @'
140. TaskForge
141.   add --title TEXT [--description TEXT] [--data-file PATH] [--json]
142.   list [--data-file PATH] [--json]
143.   complete --id ID [--data-file PATH] [--json]
144.   remove --id ID [--data-file PATH] [--json]
145.   undo [--data-file PATH] [--json]
146. '@
147.         }
148.         default {
149.             throw "Unknown command: $Command"
150.         }
151.     }
152. }
153. catch {
154.     [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
155.     exit 1
156. }
