                 throw '--id must be a positive integer.'
             }
             $tasks = @(Read-TaskStore -Path $dataFile)
             $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
             if ($null -eq $task) {
                 throw "Task $id was not found."
             }
             $index = [array]::IndexOf($tasks, $task)
             $previousTask = $task | ConvertTo-Json -Depth 8 | ConvertFrom-Json
             $task.status = 'completed'
             $undoRecord = [ordered]@{
                 operation = 'complete'
                 index = $index
                 taskId = $id
                 task = $previousTask
             }
             Write-Mutation -DataPath $dataFile -PreviousTasks @(
                 for ($current = 0; $current -lt $tasks.Count; $current++) {
                     if ($current -eq $index) { $previousTask } else { $tasks[$current] }
                 }
             ) -UpdatedTasks $tasks -UndoRecord $undoRecord
             if ($asJson) {
                 Write-TaskForgeOutput -Value $task -AsJson $true
             }
             else {
                 "Completed task $id."
             }
         }
         'remove' {
             Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json')
             $idText = Get-RequiredOption -Options $options -Name 'id'
             $id = 0
             if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                 throw '--id must be a positive integer.'
             }
             $tasks = @(Read-TaskStore -Path $dataFile)
             $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
             if ($remaining.Count -eq $tasks.Count) {
                 throw "Task $id was not found."
             }
             $removedTask = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
             $undoRecord = [ordered]@{
                 operation = 'remove'
                 index = [array]::IndexOf($tasks, $removedTask)
                 taskId = $id
                 task = $removedTask
             }
             Write-Mutation -DataPath $dataFile -PreviousTasks $tasks -UpdatedTasks $remaining -UndoRecord $undoRecord
             $summary = [pscustomobject]@{ removedId = $id }
             if ($asJson) {
                 Write-TaskForgeOutput -Value $summary -AsJson $true
             }
             else {
                 "Removed task $id."
             }
         }
         'undo' {
             Assert-KnownOptions -Options $options -Allowed @('data-file', 'json')
             $summary = Invoke-TaskUndo -DataPath $dataFile
             if ($asJson) {
                 Write-TaskForgeOutput -Value $summary -AsJson $true
             }
             else {
                 Get-Content -LiteralPath (Join-Path (Split-Path -Parent $PSScriptRoot) 'assets/undo.txt')
                 "Undid $($summary.undone) for task $($summary.taskId)."
             }
         }
         'help' {
             Assert-KnownOptions -Options $options -Allowed @()
             @'
 TaskForge
   add --title TEXT [--description TEXT] [--data-file PATH] [--json]
   list [--data-file PATH] [--json]
   complete --id ID [--data-file PATH] [--json]
   remove --id ID [--data-file PATH] [--json]
   undo [--data-file PATH] [--json]
 '@
         }
         default {
             throw "Unknown command: $Command"
         }
     }
 }
 catch {
     [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
     exit 1
 }

