+        $storeWritten = $true
+        Remove-Item -LiteralPath $claimPath -Force
+    }
+    catch {
+        if ($storeWritten) {
+            Write-TaskStore -Path $DataPath -Tasks $tasks
+        }
+        if ((Test-Path -LiteralPath $claimPath) -and -not (Test-Path -LiteralPath $undoPath)) {
+            [System.IO.File]::Move($claimPath, $undoPath)
+        }
+        throw
+    }
+
+    return [pscustomobject]@{
+        undone = $operation
+        taskId = $taskId
+    }
 }

